  1→/**
  2→ * @fileoverview WhatsApp transport adapter for the Fetch bridge.
  3→ *
  4→ * Responsibilities:
  5→ * - manage WhatsApp Web client lifecycle (auth, ready, disconnect, reconnect)
  6→ * - route inbound messages/reactions through security + handler pipeline
  7→ * - normalize transport edge cases (duplicate events, self-chat, media payloads)
  8→ * - send proactive task progress/question updates back to users
  9→ *
 10→ * @module bridge/client
 11→ * @see {@link Bridge} Runtime bridge class
 12→ */
 13→
 14→import pkg from 'whatsapp-web.js';
 15→const { Client, LocalAuth } = pkg;
 16→type Message = pkg.Message;
 17→type ClientType = InstanceType<typeof Client>;
 18→import { logger } from '../utils/logger.js';
 19→import { pipeline } from '../config/pipeline.js';
 20→import { SecurityGate, RateLimiter, validateInput } from '../security/index.js';
 21→import { handleMessage, initializeHandler, shutdown, registerWhatsAppSender } from '../handler/index.js';
 22→import { getTaskIntegration } from '../task/integration.js';
 23→import { getTaskManager } from '../task/manager.js';
 24→import { updateStatus, incrementMessageCount } from '../api/status.js';
 25→import { transcribeAudio, isTranscriptionAvailable } from '../transcription/index.js';
 26→import { analyzeImage, isVisionAvailable } from '../vision/index.js';
 27→import { composeTaskFileOpMessages, composeTaskProgressMessages, composeTaskQuestionMessages } from './progress-message.js';
 28→import * as fs from 'fs';
 29→import * as path from 'path';
 30→
 31→// =============================================================================
 32→// TASK EVENT INTERFACES
 33→// =============================================================================
 34→
 35→/** Payload shape for task:progress events */
 36→interface TaskProgressEvent {
 37→  sessionId?: string;
 38→  message?: string;
 39→}
 40→
 41→/** Payload shape for task:file_op events */
 42→interface TaskFileOpEvent {
 43→  sessionId?: string;
 44→  operation?: string;
 45→  path?: string;
 46→}
 47→
 48→/** Payload shape for task:question events */
 49→interface TaskQuestionEvent {
 50→  sessionId?: string;
 51→  question?: string;
 52→}
 53→
 54→// =============================================================================
 55→// CHROME LOCK CLEANUP
 56→// =============================================================================
 57→
 58→/**
 59→ * Remove stale Chromium singleton lock files under WhatsApp auth data.
 60→ *
 61→ * This runs before client init/re-init to avoid Chromium startup failures
 62→ * after unclean shutdowns.
 63→ *
 64→ * @param authPath - Path to the .wwebjs_auth directory
 65→ */
 66→function cleanupChromeLocks(authPath: string): void {
 67→  const lockNames = new Set(['SingletonLock', 'SingletonCookie', 'SingletonSocket']);
 68→
 69→  try {
 70→    if (!fs.existsSync(authPath)) {
 71→      return; // No auth directory yet, nothing to clean
 72→    }
 73→
 74→    // Find session directories (session / session-* folders)
 75→    const topEntries = fs.readdirSync(authPath, { withFileTypes: true });
 76→
 77→    for (const entry of topEntries) {
 78→      if (!entry.isDirectory() || !entry.name.startsWith('session')) continue;
 79→
 80→      const sessionPath = path.join(authPath, entry.name);
 81→
 82→      // Directories to scan: the session root and its Default/ subfolder
 83→      const dirsToScan = [sessionPath];
 84→      const defaultPath = path.join(sessionPath, 'Default');
 85→      try { if (fs.statSync(defaultPath).isDirectory()) dirsToScan.push(defaultPath); } catch { /* no Default dir */ }
 86→
 87→      for (const dir of dirsToScan) {
 88→        // readdirSync lists ALL directory entries including broken symlinks
 89→        let entries: string[];
 90→        try { entries = fs.readdirSync(dir); } catch { continue; }
 91→
 92→        for (const name of entries) {
 93→          if (!lockNames.has(name)) continue;
 94→          const lockPath = path.join(dir, name);
 95→          try {
 96→            fs.unlinkSync(lockPath);
 97→            logger.info(`🧹 Cleaned up stale Chrome lock: ${dir}/${name}`);
 98→          } catch (e) {
 99→            logger.warn(`Could not remove lock ${lockPath}: ${e}`);
100→          }
101→        }
102→      }
103→    }
104→  } catch (error) {
105→    logger.warn(`Could not clean Chrome locks: ${error}`);
106→  }
107→}
108→
109→// =============================================================================
110→// MESSAGE DEDUPLICATION
111→// =============================================================================
112→
113→/**
114→ * Deduplicate inbound `message_create` events by message id with TTL eviction.
115→ */
116→class MessageDeduplicator {
117→  private processedMessages = new Map<string, number>();
118→  private readonly TTL_MS = pipeline.deduplicationTtl;
119→  private cleanupTimer: ReturnType<typeof setInterval>;
120→
121→  constructor() {
122→    // Sweep every TTL interval instead of per-message
123→    this.cleanupTimer = setInterval(() => this.evict(), this.TTL_MS);
124→    this.cleanupTimer.unref();
125→  }
126→
127→  /**
128→   * Mark and check message id.
129→   *
130→   * @returns `true` if message id was not seen in the current TTL window
131→   */
132→  isNew(messageId: string): boolean {
133→    if (this.processedMessages.has(messageId)) {
134→      return false;
135→    }
136→    this.processedMessages.set(messageId, Date.now());
137→    return true;
138→  }
139→
140→  /** Remove cached ids older than TTL. */
141→  private evict(): void {
142→    const cutoff = Date.now() - this.TTL_MS;
143→    for (const [id, ts] of this.processedMessages) {
144→      if (ts <= cutoff) this.processedMessages.delete(id);
145→    }
146→  }
147→}
148→
149→// =============================================================================
150→// BRIDGE CLASS
151→// =============================================================================
152→
153→/**
154→ * Runtime wrapper around `whatsapp-web.js` client.
155→ *
156→ * Owns client lifecycle, event wiring, inbound security checks, and outbound
157→ * proactive messaging integration.
158→ */
159→export class Bridge {
160→  private client: ClientType;
161→  private securityGate: SecurityGate;
162→  private rateLimiter: RateLimiter;
163→  private deduplicator = new MessageDeduplicator();
164→  private reactionDedup = new Map<string, number>();
165→  private botRecentMessageIds: string[] = []; // LRU cache for bot sent messages
166→  private readonly maxBotRecentMessages = 1000;
167→  private isReady = false;
168→  private readyAt = 0;
169→  private readonly reactionWarmupMs = 60_000;
170→  private readonly reactionDedupTtlMs = 10_000;
171→
172→  // Reconnection state
173→  private reconnectAttempts = 0;
174→  private readonly maxReconnectAttempts = pipeline.maxReconnectAttempts;
175→  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
176→  private isReconnecting = false;
177→  private destroyed = false;
178→
179→  /**
180→   * Disconnection reasons that should not trigger automatic reconnect loops.
181→   *
182→   * QR retry exhaustion is an operator-driven state (no scan happened), not a
183→   * transient transport failure. Auto-retrying immediately just recreates QR
184→   * churn and reaches the same terminal reason again.
185→   */
186→  private shouldPauseAutoReconnect(reason: string): boolean {
187→    const normalized = reason.toLowerCase();
188→    return normalized.includes('max qrcode retries reached');
189→  }
190→
191→  constructor() {
192→    this.client = new Client({
193→      authStrategy: new LocalAuth({
194→        dataPath: '/app/data/.wwebjs_auth'
195→      }),
196→      // QR code settings - refresh every 20 seconds (default is 45)
197→      qrMaxRetries: 10,
198→      puppeteer: {
199→        headless: true,
200→        args: [
201→          '--no-sandbox',
202→          '--disable-setuid-sandbox',
203→          '--disable-dev-shm-usage',
204→          '--disable-accelerated-2d-canvas',
205→          '--no-first-run',
206→          '--no-zygote',
207→          '--disable-gpu'
208→        ]
209→      }
210→    });
211→
212→    // SecurityGate initialized in initialize() for async whitelist loading
213→    this.securityGate = null as unknown as SecurityGate;
214→    this.rateLimiter = new RateLimiter(pipeline.rateLimitMax, pipeline.rateLimitWindow);
215→  }
216→
217→  /**
218→   * Initialize security, handler integrations, event listeners, and WhatsApp client.
219→   */
220→  async initialize(): Promise<void> {
221→    // Clean up any stale Chrome lock files from previous crashes
222→    cleanupChromeLocks('/app/data/.wwebjs_auth');
223→
224→    // Initialize security gate with Zero Trust Bonding whitelist
225→    this.securityGate = await SecurityGate.create();
226→
227→    // Initialize agentic handler
228→    await initializeHandler();
229→
230→    // Register WhatsApp sender for proactive messages (task completions, etc.)
231→    registerWhatsAppSender(async (userId: string, text: string) => {
232→      try {
233→        logger.info(`Sending proactive message to ${userId}`);
234→        const targetId = userId.includes('@') ? userId : `${userId}@c.us`;
235→        const sentMsg = await this.client.sendMessage(targetId, text);
236→        if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
237→          this.trackBotMessage(sentMsg.id._serialized);
238→        }
239→        logger.success(`Proactive message sent to ${targetId}`);
240→      } catch (err) {
241→        logger.error(`Failed to send proactive WhatsApp message to ${userId}`, err);
242→      }
243→    });
244→
245→    this.setupEventHandlers();
246→    this.setupTaskProgressListeners();
247→    await this.client.initialize();
248→  }
249→
250→  /**
251→   * Register WhatsApp client event handlers (connection, messages, reactions).
252→   */
253→  private setupEventHandlers(): void {
254→    // QR Code for authentication
255→    this.client.on('qr', (qr: string) => {
256→      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qr)}`;
257→
258→      // Update status API
259→      updateStatus({
260→        state: 'qr_pending',
261→        qrCode: qr,
262→        qrUrl: qrUrl
263→      });
264→
265→      // Console output - show URL only (QR too large for terminal)
266→      console.log('');
267→      console.log('╔══════════════════════════════════════════════════╗');
268→      console.log('║  📱 WhatsApp Authentication Required              ║');
269→      console.log('╚══════════════════════════════════════════════════╝');
270→      console.log('');
271→      console.log('  Open this URL to see QR code:');
272→      console.log(`  ${qrUrl}`);
273→      console.log('');
274→      console.log('  📲 WhatsApp → Settings → Linked Devices → Link');
275→      console.log('');
276→    });
277→
278→    // Ready event
279→    this.client.on('ready', () => {
280→      updateStatus({ state: 'authenticated', qrCode: null, qrUrl: null });
281→
282→      // Reset reconnection state on successful connection
283→      if (this.isReconnecting) {
284→        logger.success(`WhatsApp reconnected after ${this.reconnectAttempts} attempt(s)`);
285→      }
286→      this.reconnectAttempts = 0;
287→      this.isReconnecting = false;
288→      this.isReady = true;
289→      this.readyAt = Date.now();
290→
291→      logger.section('🐕 Fetch is Ready!');
292→      logger.success('WhatsApp connected and listening for commands');
293→      logger.info('Send a message starting with @fetch to interact');
294→      logger.divider();
295→    });
296→
297→    // Authentication success
298→    this.client.on('authenticated', () => {
299→      updateStatus({ state: 'authenticated', qrCode: null, qrUrl: null });
300→      logger.success('WhatsApp authentication successful');
301→    });
302→
303→    // Authentication failure
304→    this.client.on('auth_failure', (msg: string) => {
305→      updateStatus({ state: 'error', lastError: msg });
306→      logger.error('WhatsApp authentication failed', msg);
307→    });
308→
309→    // Disconnected — attempt reconnection with exponential backoff
310→    this.client.on('disconnected', (reason: string) => {
311→      updateStatus({ state: 'disconnected', lastError: reason });
312→      logger.warn('WhatsApp disconnected', reason);
313→
314→      // Attempt reconnection unless intentionally destroyed
315→      if (!this.destroyed) {
316→        if (this.shouldPauseAutoReconnect(reason)) {
317→          if (this.reconnectTimer) {
318→            clearTimeout(this.reconnectTimer);
319→            this.reconnectTimer = null;
320→          }
321→          this.isReconnecting = false;
322→          this.reconnectAttempts = 0;
323→          logger.warn(
324→            'Auto-reconnect paused after QR retry exhaustion; waiting for manual restart/setup',
325→          );
326→          return;
327→        }
328→        this.reconnect();
329→      }
330→    });
331→
332→    // ==========================================================================
333→    // MESSAGE REACTION HANDLER
334→    // Emoji reactions like 👍, ❤️, etc. on messages
335→    // ==========================================================================
336→    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js has no typed Reaction export
337→    this.client.on('message_reaction', async (reaction: any) => {
338→      try {
339→        // 1. Skip if bridge not fully ready (prevents startup sync spam)
340→        if (!this.isReady) return;
341→        if (Date.now() - this.readyAt < this.reactionWarmupMs) {
342→          logger.debug('Skipped reaction during startup warmup');
343→          return;
344→        }
345→
346→        // 2. Only process reactions from owner or trusted whitelist members
347→        const senderId = reaction.senderId;
348→        if (!senderId || !this.securityGate.isAuthorizedUser(senderId)) {
349→          // Log only at debug level to keep the main logs clean
350→          logger.debug(`Skipped unauthorized reaction from: ${senderId}`);
351→          return;
352→        }
353→
354→        // 3. Only process reactions on our messages (fromMe)
355→        const msgId = reaction.msgId;
356→        if (!msgId) return;
357→
358→        const emoji = reaction.reaction;
359→        const serializedMsgId = msgId._serialized || String(msgId);
360→        const dedupKey = `${senderId}:${serializedMsgId}:${emoji}`;
361→        const now = Date.now();
362→        const lastSeen = this.reactionDedup.get(dedupKey);
363→        if (lastSeen && (now - lastSeen) < this.reactionDedupTtlMs) {
364→          logger.debug(`Skipped duplicate reaction: ${dedupKey}`);
365→          return;
366→        }
367→        this.reactionDedup.set(dedupKey, now);
368→        for (const [k, ts] of this.reactionDedup) {
369→          if ((now - ts) > this.reactionDedupTtlMs) this.reactionDedup.delete(k);
370→        }
371→
372→        logger.info(`Reaction received: ${emoji} from authorized user on message ${serializedMsgId}`);
373→
374→        // Map reactions to actions
375→        // 👍 = approve/continue, 👎 = cancel/reject, ❌ = cancel
376→        const approveEmojis = ['👍', '✅', '👌', '🙌', '💯'];
377→        const rejectEmojis = ['👎', '❌', '🚫', '⛔'];
378→        const cancelEmojis = ['🛑', '⏹️', '❌'];
379→        const taskManager = await getTaskManager();
380→        const currentTask = taskManager.getCurrentTask();
381→        const awaitingInput = currentTask?.status === 'waiting_input';
382→
383→        if (!awaitingInput) {
384→          logger.debug('Ignored reaction approval: no task awaiting input');
385→          return;
386→        }
387→
388→        if (approveEmojis.includes(emoji)) {
389→          logger.info('Processing approval via reaction');
390→          const responses = await handleMessage(senderId, 'yes');
391→          for (const response of responses) {
392→            await this.client.sendMessage(senderId, response);
393→          }
394→        } else if (rejectEmojis.includes(emoji) || cancelEmojis.includes(emoji)) {
395→          logger.info('Processing rejection/cancel via reaction');
396→          const responses = await handleMessage(senderId, 'no');
397→          for (const response of responses) {
398→            await this.client.sendMessage(senderId, response);
399→          }
400→        }
401→        // Other emojis are ignored (just acknowledgements)
402→      } catch (error) {
403→        logger.error('Failed to process reaction', error);
404→      }
405→    });
406→
407→    // ==========================================================================
408→    // MESSAGE HANDLERS
409→    // ==========================================================================
410→
411→    // Use message_create to catch ALL messages including self-chat
412→    this.client.on('message_create', async (message: Message) => {
413→      // DEDUPLICATION: WhatsApp fires message_create multiple times for same message
414→      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js Message.id not in type defs
415→      const msgId = (message as any).id?._serialized || (message as any).id?.id || String(message.timestamp);
416→      if (!this.deduplicator.isNew(msgId)) {
417→        logger.debug(`Skipped duplicate message: ${msgId}`);
418→        return;
419→      }
420→
421→      logger.debug(`message_create: from=${message.from}, type=${message.type}, fromMe=${message.fromMe}`);
422→
423→      // Handle Voice Notes (PTT)
424→      if (message.type === 'ptt' || message.type === 'audio') {
425→        const success = await this.handleVoiceMessage(message);
426→        if (!success) {
427→          logger.debug('Skipped: voice transcription failed or not available');
428→          return;
429→        }
430→      }
431→
432→      // Handle Images
433→      if (message.type === 'image') {
434→        await this.handleImageMessage(message);
435→        // Note: we don't return if it fails, as it might still have a text caption
436→      }
437→
438→      // Skip empty messages (media without caption, etc.)
439→      if (!message.body || message.body.trim() === '') {
440→        logger.debug('Skipped: empty message body');
441→        return;
442→      }
443→
444→      // Check if this is a reply to a Fetch message (thread continuation)
445→      const isReplyToFetch = message.fromMe ? false : await this.isReplyToFetchMessage(message);
446→      const hasFetchTrigger = message.body.toLowerCase().trim().startsWith('@fetch');
447→
448→      // For messages from us (fromMe=true), ONLY process with explicit @fetch trigger.
449→      // Thread replies are disabled for fromMe to prevent infinite response loops.
450→      if (message.fromMe) {
451→        if (!hasFetchTrigger) {
452→          return;
453→        }
454→        logger.info('Processing self-chat message');
455→      } else {
456→        // For messages from others, allow @fetch trigger OR reply to a Fetch message
457→        if (!hasFetchTrigger && !isReplyToFetch) {
458→          return;
459→        }
460→        logger.info(`Processing incoming message from ${message.from}${isReplyToFetch ? ' (thread reply)' : ''}`);
461→      }
462→
463→      incrementMessageCount();
464→      await this.handleIncomingMessage(message, isReplyToFetch);
465→    });
466→  }
467→
468→  /**
469→   * Tracks a message ID sent by the bot to allow thread replies out of the group.
470→   * Keeps a bounded list of recent IDs.
471→   */
472→  private trackBotMessage(messageId: string): void {
473→    this.botRecentMessageIds.push(messageId);
474→    if (this.botRecentMessageIds.length > this.maxBotRecentMessages) {
475→      this.botRecentMessageIds.shift(); // Remove oldest
476→    }
477→  }
478→
479→  /**
480→   * Check if message is a reply to a Fetch bot message
481→   */
482→  private async isReplyToFetchMessage(message: Message): Promise<boolean> {
483→    try {
484→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
485→      const quotedMsg = await (message as any).getQuotedMessage();
486→      if (!quotedMsg || !quotedMsg.id || !quotedMsg.id._serialized) return false;
487→
488→      // Check if the quoted message's ID is in our cache of recent bot-sent messages
489→      if (this.botRecentMessageIds.includes(quotedMsg.id._serialized)) {
490→        logger.debug('Message is reply to Fetch response');
491→        return true;
492→      }
493→      return false;
494→    } catch {
495→      return false;
496→    }
497→  }
498→
499→  /**
500→   * Download and analyze image messages, then append analysis to message body.
501→   *
502→   * @returns `true` when analysis context was added to the message
503→   */
504→  private async handleImageMessage(message: Message): Promise<boolean> {
505→    if (!isVisionAvailable()) {
506→      logger.warn('Image received but vision is not configured (missing API key)');
507→      return false;
508→    }
509→
510→    try {
511→      logger.info('🖼️ Processing image...');
512→
513→      const media = await message.downloadMedia();
514→      if (!media || !media.data) {
515→        logger.error('Failed to download image media');
516→        return false;
517→      }
518→
519→      // If it's not an image, skip
520→      if (!media.mimetype.startsWith('image/')) {
521→        return false;
522→      }
523→
524→      const originalCaption = message.body || '';
525→      const analysis = await analyzeImage(media.data, media.mimetype, originalCaption);
526→
527→      if (!analysis) return false;
528→
529→      // Update message body to include analysis context
530→      message.body = `${originalCaption}\n\n[CONTEXT: Image Analysis]\n${analysis}`.trim();
531→
532→      logger.success('🖼️ Image analysis added to message context');
533→      return true;
534→    } catch (error) {
535→      logger.error('Failed to handle image message', error);
536→      return false;
537→    }
538→  }
539→
540→  /**
541→   * Subscribe to task integration events and forward user-facing updates.
542→   */
543→  private setupTaskProgressListeners(): void {
544→    const integration = getTaskIntegration();
545→
546→    // Mapping to track last progress message per session to avoid noise
547→    const lastProgressUpdate = new Map<string, number>();
548→    const THROTTLE_MS = pipeline.progressThrottle; // Minimum time between general progress updates
549→
550→    // Helper to resolve user ID from session ID
551→    const resolveTarget = async (sessionId: string): Promise<string | null> => {
552→      if (!sessionId) return null;
553→      // If it looks like a JID, use it directly (legacy/direct support)
554→      if (sessionId.includes('@c.us') || sessionId.includes('@g.us')) return sessionId;
555→
556→      // Otherwise, resolve via SessionManager
557→      try {
558→        const { getSessionManager } = await import('../session/manager.js');
559→        const manager = await getSessionManager();
560→        const session = await manager.getSessionById(sessionId);
561→        return session ? session.userId : null;
562→      } catch (_err) {
563→        logger.warn('Failed to resolve session owner', { sessionId });
564→        return null;
565→      }
566→    };
567→
568→    // Codex emits structured JSONL lifecycle events on stdout. These are
569→    // useful for internal telemetry but should never be forwarded verbatim
570→    // to WhatsApp users.
571→    const isStructuredHarnessEventLine = (raw: string): boolean => {
572→      const line = raw.trim();
573→      if (!line.startsWith('{') || !line.endsWith('}')) return false;
574→      try {
575→        const parsed = JSON.parse(line) as { type?: unknown; item?: { type?: unknown } };
576→        const type = typeof parsed.type === 'string' ? parsed.type : '';
577→        if (
578→          type.startsWith('thread.') ||
579→          type.startsWith('turn.') ||
580→          type.startsWith('item.')
581→        ) {
582→          return true;
583→        }
584→        const itemType = typeof parsed.item?.type === 'string' ? parsed.item.type : '';
585→        return itemType === 'command_execution' || itemType === 'reasoning' || itemType === 'file_change';
586→      } catch {
587→        return false;
588→      }
589→    };
590→
591→    integration.on('task:progress', async (event: TaskProgressEvent) => {
592→      const { sessionId, message } = event;
593→      if (!sessionId || !message) return;
594→      if (isStructuredHarnessEventLine(message)) return;
595→
596→      const targetId = await resolveTarget(sessionId);
597→      if (!targetId) return;
598→
599→      const now = Date.now();
600→      const lastUpdate = lastProgressUpdate.get(sessionId) || 0;
601→
602→      // Always send priority patterns, throttle others
603→      const isPriority = /starting|done|complete|failed|error|waiting/i.test(message);
604→
605→      if (isPriority || (now - lastUpdate > THROTTLE_MS)) {
606→        try {
607→          const chunks = await composeTaskProgressMessages(message, sessionId);
608→          for (const chunk of chunks) {
609→            const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
610→            if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
611→              this.trackBotMessage(sentMsg.id._serialized);
612→            }
613→          }
614→          lastProgressUpdate.set(sessionId, now);
615→        } catch (error) {
616→          logger.error('Failed to send progress message', error);
617→        }
618→      }
619→    });
620→
621→    integration.on('task:file_op', async (event: TaskFileOpEvent) => {
622→      const { sessionId, operation, path } = event;
623→      if (!sessionId || !operation || !path) return;
624→
625→      const targetId = await resolveTarget(sessionId);
626→      if (!targetId) return;
627→
628→      try {
629→        const chunks = composeTaskFileOpMessages(operation, path);
630→        for (const chunk of chunks) {
631→          const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
632→          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
633→            this.trackBotMessage(sentMsg.id._serialized);
634→          }
635→        }
636→      } catch (error) {
637→        logger.error('Failed to send file_op message', error);
638→      }
639→    });
640→
641→    integration.on('task:question', async (event: TaskQuestionEvent) => {
642→      const { sessionId, question } = event;
643→      if (!sessionId || !question) return;
644→
645→      const targetId = await resolveTarget(sessionId);
646→      if (!targetId) return;
647→
648→      try {
649→        const chunks = composeTaskQuestionMessages(question);
650→        for (const chunk of chunks) {
651→          const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
652→          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
653→            this.trackBotMessage(sentMsg.id._serialized);
654→          }
655→        }
656→      } catch (error) {
657→        logger.error('Failed to send task question', error);
658→      }
659→    });
660→  }
661→
662→  /**
663→   * Transcribe incoming voice notes and replace message body with transcript.
664→   *
665→   * @returns `true` when transcription succeeded and body was updated
666→   */
667→  private async handleVoiceMessage(message: Message): Promise<boolean> {
668→    if (!isTranscriptionAvailable()) {
669→      logger.warn('Voice message received but transcription is not configured (missing API key)');
670→      return false;
671→    }
672→
673→    try {
674→      logger.info('🎤 Processing voice note...');
675→
676→      const media = await message.downloadMedia();
677→
678→      const buffer = Buffer.from(media.data, 'base64');
679→      const filename = media.filename || `voice-${Date.now()}.ogg`;
680→
681→      const result = await transcribeAudio(buffer, filename);
682→      const transcription = result.text;
683→
684→      if (!transcription || transcription.trim().length === 0) {
685→        logger.warn('Transcription returned empty text');
686→        return false;
687→      }
688→
689→      // Prepend a microphone emoji to indicate it was a voice note
690→      // and inject into the message body for normal processing
691→      message.body = transcription;
692→
693→      logger.success(`🎤 Transcribed voice (${result.language || 'unknown'}): "${transcription}"`);
694→      return true;
695→    } catch (error) {
696→      logger.error('Failed to handle voice message', error);
697→      return false;
698→    }
699→  }
700→
701→  /**
702→   * Process one inbound message through auth, rate limiting, validation, and handler execution.
703→   */
704→  private async handleIncomingMessage(message: Message, isThreadReply: boolean = false): Promise<void> {
705→    const senderId = message.from;
706→    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js Message.author not in type defs
707→    const participantId = (message as any).author; // Group message author
708→    const messageBody = message.body;
709→
710→    // SECURITY GATE 1: Validate authorization
711→    // For thread replies, we skip the @fetch trigger check but still verify identity
712→    if (isThreadReply) {
713→      // For thread replies, verify owner OR trusted whitelist member (no @fetch required)
714→      const isGroup = senderId.endsWith('@g.us');
715→      const checkId = isGroup ? participantId : senderId;
716→      if (!checkId) return;
717→      if (!this.securityGate.isOwnerMessage(senderId, participantId) &&
718→        !this.securityGate.getWhitelist()?.has(checkId.replace(/@(c|g|s)\.us$/, '').replace(/\D/g, '') || '')) {
719→        return;
720→      }
721→    } else {
722→      // Normal flow: require @fetch trigger + (owner OR trusted)
723→      if (!this.securityGate.isAuthorized(senderId, participantId, messageBody)) {
724→        return;
725→      }
726→    }
727→
728→    // Strip the @fetch trigger from the message (if present)
729→    const command = this.securityGate.stripTrigger(messageBody);
730→
731→    // SECURITY GATE 2: Rate limiting
732→    const rateLimitId = participantId || senderId;
733→    const sessionUserId = await this.resolveCanonicalSessionUserId(message, senderId, participantId);
734→    if (!(await this.rateLimiter.isAllowed(rateLimitId))) {
735→      await message.reply('⏳ Slow down! You\'re sending too many requests. Please wait a moment.');
736→      return;
737→    }
738→
739→    // SECURITY GATE 3: Input validation
740→    const validation = validateInput(command);
741→    if (!validation.valid) {
742→      logger.warn(`Invalid input from owner: ${validation.error}`);
743→      await message.reply(`❌ ${validation.error}`);
744→      return;
745→    }
746→
747→    logger.message(`Received: "${validation.sanitized.substring(0, 40)}${validation.sanitized.length > 40 ? '...' : ''}"`);
748→
749→    try {
750→      let firstMessageSent = false;
751→
752→      // Determine prefix for different media types
753→      let mediaPrefix = '';
754→      if (message.type === 'ptt' || message.type === 'audio') {
755→        mediaPrefix = `🎤 I heard: "${validation.sanitized}"\n\n`;
756→      } else if (message.type === 'image') {
757→        mediaPrefix = `🖼️ I see an image!\n\n`;
758→        // Optional: you could extract the summary from the analysis here if desired
759→      }
760→
761→      // Process through agentic handler
762→      const responses = await handleMessage(
763→        sessionUserId,
764→        validation.sanitized,
765→        async (text) => {
766→          let output = text;
767→          if (!firstMessageSent && mediaPrefix) {
768→            output = mediaPrefix + output;
769→            firstMessageSent = true;
770→          }
771→          const sentMsg = await message.reply(output);
772→          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
773→            this.trackBotMessage(sentMsg.id._serialized);
774→          }
775→        }
776→      );
777→
778→      // Send all response messages
779→      for (let i = 0; i < responses.length; i++) {
780→        let response = responses[i];
781→
782→        // Prepend media info prefix if it was a voice note or image and we haven't sent the prefix yet
783→        if (!firstMessageSent && mediaPrefix) {
784→          response = mediaPrefix + response;
785→          firstMessageSent = true; // Mark as sent so subsequent responses don't get it
786→        }
787→
788→        const sentMsg = await message.reply(response);
789→        if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
790→          this.trackBotMessage(sentMsg.id._serialized);
791→        }
792→        logger.success(`Reply sent (${response.length} chars)`);
793→
794→        // Small delay between messages to avoid rate limiting
795→        if (responses.length > 1 && i < responses.length - 1) {
796→          await new Promise(resolve => setTimeout(resolve, 500));
797→        }
798→      }
799→    } catch (error) {
800→      logger.error('Failed to process message', error);
801→      await message.reply('❌ Sorry, I encountered an error processing your request.');
802→    }
803→  }
804→
805→  /**
806→   * Resolve a stable per-user session identifier.
807→   *
808→   * Prefer phone-number JIDs (e.g. `15551234567@c.us`) so sessions don't bind
809→   * to opaque WhatsApp LID identifiers (`...@lid`) when a number is available.
810→   */
811→  private async resolveCanonicalSessionUserId(
812→    message: Message,
813→    senderId: string,
814→    participantId: string | undefined,
815→  ): Promise<string> {
816→    const isGroup = senderId.endsWith('@g.us');
817→    const baseId = (isGroup ? (participantId || senderId) : senderId) || senderId;
818→
819→    // Already canonical.
820→    if (baseId.endsWith('@c.us')) {
821→      return baseId;
822→    }
823→
824→    try {
825→      const contact = await message.getContact();
826→      // whatsapp-web.js commonly exposes `number` and `id._serialized`.
827→      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- runtime shape varies by WA account mode
828→      const contactAny = contact as any;
829→      const number = String(contactAny?.number || '').replace(/\D/g, '');
830→      if (number.length >= 10 && number.length <= 15) {
831→        return `${number}@c.us`;
832→      }
833→
834→      const serialized = String(contactAny?.id?._serialized || '');
835→      if (serialized.endsWith('@c.us')) {
836→        return serialized;
837→      }
838→    } catch {
839→      // Ignore contact lookup failures and continue with fallback normalization.
840→    }
841→
842→    const atIndex = baseId.indexOf('@');
843→    const local = atIndex >= 0 ? baseId.slice(0, atIndex) : baseId;
844→    const digits = local.replace(/\D/g, '');
845→    if (digits.length >= 10 && digits.length <= 15) {
846→      return `${digits}@c.us`;
847→    }
848→
849→    return baseId;
850→  }
851→
852→  // ===========================================================================
853→  // RECONNECTION
854→  // ===========================================================================
855→
856→  /**
857→   * Recreate and reinitialize the WhatsApp client using exponential backoff.
858→   */
859→  private reconnect(): void {
860→    if (this.destroyed || this.isReconnecting) return;
861→
862→    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
863→      logger.error(
864→        `WhatsApp reconnection failed after ${this.maxReconnectAttempts} attempts — giving up`,
865→      );
866→      updateStatus({ state: 'error', lastError: 'Max reconnection attempts exceeded' });
867→      return;
868→    }
869→
870→    this.isReconnecting = true;
871→    this.reconnectAttempts++;
872→
873→    // Exponential backoff with configurable base, cap, and jitter
874→    const BASE_DELAY = pipeline.reconnectBaseDelay;
875→    const MAX_DELAY = pipeline.reconnectMaxDelay;
876→    const jitter = Math.random() * pipeline.reconnectJitter;
877→    const delay =
878→      Math.min(BASE_DELAY * Math.pow(2, this.reconnectAttempts - 1), MAX_DELAY) + jitter;
879→
880→    logger.info(
881→      `🔄 Reconnecting in ${(delay / 1000).toFixed(1)}s ` +
882→      `(attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})…`,
883→    );
884→
885→    this.reconnectTimer = setTimeout(async () => {
886→      this.reconnectTimer = null;
887→
888→      try {
889→        // Destroy the old client cleanly
890→        try { await this.client.destroy(); } catch { /* already dead */ }
891→
892→        // Fresh Client instance — wweb can't re-initialize the same one
893→        this.client = new Client({
894→          authStrategy: new LocalAuth({
895→            dataPath: '/app/data/.wwebjs_auth',
896→          }),
897→          qrMaxRetries: 10,
898→          puppeteer: {
899→            headless: true,
900→            args: [
901→              '--no-sandbox',
902→              '--disable-setuid-sandbox',
903→              '--disable-dev-shm-usage',
904→              '--disable-accelerated-2d-canvas',
905→              '--no-first-run',
906→              '--no-zygote',
907→              '--disable-gpu',
908→            ],
909→          },
910→        });
911→
912→        // Re-bind event handlers on the new client
913→        // (Task progress listeners reference `this.client` via `this`, so they
914→        //  already point at the new instance — no need to re-register.)
915→        this.setupEventHandlers();
916→        cleanupChromeLocks('/app/data/.wwebjs_auth');
917→
918→        await this.client.initialize();
919→        // On success the 'ready' handler resets reconnect state
920→      } catch (error) {
921→        const msg = error instanceof Error ? error.message : String(error);
922→        logger.error(`Reconnection attempt ${this.reconnectAttempts} failed: ${msg}`);
923→        this.isReconnecting = false;
924→
925→        // Schedule next attempt
926→        this.reconnect();
927→      }
928→    }, delay);
929→  }
930→
931→  // ===========================================================================
932→  // LIFECYCLE
933→  // ===========================================================================
934→
935→  /**
936→   * Stop bridge processing and destroy the WhatsApp client instance.
937→   */
938→  async destroy(): Promise<void> {
939→    this.destroyed = true;
940→
941→    // Cancel any pending reconnection
942→    if (this.reconnectTimer) {
943→      clearTimeout(this.reconnectTimer);
944→      this.reconnectTimer = null;
945→    }
946→
947→    this.rateLimiter.shutdown();
948→    await this.securityGate.shutdown();
949→    await shutdown();
950→    await this.client.destroy();
951→  }
952→}
