  9→import 'dotenv/config';
 10→import { pathToFileURL } from 'url';
 11→import { Bridge } from './bridge/client.js';
 12→import { logger } from './utils/logger.js';
 13→import { startStatusServer, setLogoutCallback, setWhatsAppControlCallbacks, updateStatus } from './api/status.js';
 14→import { validateEnv } from './config/env.js';
 15→import { getSessionStore } from './session/store.js';
 16→import { getTaskStore } from './task/store.js';
 17→import { getSkillManager } from './skills/manager.js';
 18→import { getIdentityManager } from './identity/manager.js';
 19→import { getToolRegistry } from './tools/registry.js';
 20→import { getVersion } from './utils/version.js';
 21→import { getWorkflowManager, shutdownWorkflowManager } from './workflow/manager.js';
 22→
 23→type ExitFn = (code: number) => void;
 24→
 25→interface RuntimeOptions {
 26→  exit?: ExitFn;
 27→}
 28→
 29→interface Runtime {
 30→  main: () => Promise<void>;
 31→  shutdown: (signal: string) => Promise<void>;
 32→  registerProcessHandlers: () => void;
 33→}
 34→
 35→/**
 36→ * Creates an app runtime with injectable process-exit behavior for tests.
 37→ */
 38→export function createRuntime(options: RuntimeOptions = {}): Runtime {
 39→  const exit = options.exit ?? ((code: number) => process.exit(code));
 40→
 41→  let activeBridge: Bridge | null = null;
 42→  let shuttingDown = false;
 43→  let handlersRegistered = false;
 44→  let bootstrapTimer: ReturnType<typeof setInterval> | null = null;
 45→  let bridgeStarting = false;
 46→  let workflowInitialized = false;
 47→  let bridgeRequested = false;
 48→
 49→  const clearBootstrapTimer = (): void => {
 50→    if (bootstrapTimer) {
 51→      clearInterval(bootstrapTimer);
 52→      bootstrapTimer = null;
 53→    }
 54→  };
 55→
 56→  const startBridge = async (): Promise<void> => {
 57→    if (bridgeStarting || shuttingDown || activeBridge) return;
 58→    bridgeStarting = true;
 59→
 60→    try {
 61→      const { valid, missing } = validateEnv();
 62→      if (!valid) {
 63→        const missingMsg = `Setup required: missing ${missing.join(', ')}`;
 64→        updateStatus({ state: 'error', lastError: missingMsg });
 65→        logger.warn(missingMsg);
 66→        return;
 67→      }
 68→
 69→      clearBootstrapTimer();
 70→
 71→      // Load skills (builtin + user) before bridge starts accepting messages
 72→      await getSkillManager().init();
 73→
 74→      const bridge = new Bridge();
 75→      await bridge.initialize();
 76→      activeBridge = bridge;
 77→
 78→      // Register logout callback for the status API
 79→      setLogoutCallback(async () => {
 80→        logger.info('🔌 Logout requested via API, destroying bridge...');
 81→        await bridge.destroy();
 82→        activeBridge = null;
 83→        logger.info('✅ Bridge destroyed, WhatsApp disconnected');
 84→      });
 85→
 86→      logger.info('✅ Fetch Bridge is ready and listening!');
 87→    } catch (error) {
 88→      const errorMessage = error instanceof Error ? error.message : String(error);
 89→      const errorStack = error instanceof Error ? error.stack : undefined;
 90→      logger.error('Failed to initialize Fetch Bridge:', { message: errorMessage, stack: errorStack });
 91→      updateStatus({ state: 'error', lastError: errorMessage });
 92→      logger.warn('Bridge initialization failed; runtime will remain alive and retry.');
 93→    } finally {
 94→      bridgeStarting = false;
 95→    }
 96→  };
 97→
 98→  const requestBridgeStart = async (): Promise<void> => {
 99→    bridgeRequested = true;
100→    await startBridge();
101→  };
102→
103→  const restartBridge = async (): Promise<void> => {
104→    if (bridgeStarting || shuttingDown) return;
105→    try {
106→      if (activeBridge) {
107→        await activeBridge.destroy();
108→        activeBridge = null;
109→      }
110→      updateStatus({ state: 'initializing', lastError: null, qrCode: null, qrUrl: null });
111→    } catch (error) {
112→      logger.warn('Failed to fully destroy bridge during restart, continuing', error);
113→    }
114→    bridgeRequested = true;
115→    await startBridge();
116→  };
117→
118→  const main = async (): Promise<void> => {
119→    const version = getVersion();
120→    logger.info(`Fetch Bridge ${version} starting...`);
121→
122→    // Start status API first so TUI can configure missing env in setup mode.
123→    startStatusServer();
124→    setWhatsAppControlCallbacks({
125→      start: requestBridgeStart,
126→      restart: restartBridge,
127→    });
128→
129→    if (!workflowInitialized) {
130→      await getWorkflowManager();
131→      workflowInitialized = true;
132→    }
133→
134→    // Stay alive in setup mode; start WhatsApp only when explicitly requested.
135→    updateStatus({ state: 'disconnected', lastError: 'WhatsApp not started. Open Setup WhatsApp to begin pairing.' });
136→    if (!activeBridge && !shuttingDown) {
137→      bootstrapTimer = setInterval(() => {
138→        if (bridgeRequested) {
