/**
 * @fileoverview Abstract messaging bridge interface for multi-platform support.
 *
 * All messaging platforms (WhatsApp, Slack, Telegram, Discord) implement this
 * interface so the handler and task layers remain transport-agnostic.
 *
 * @module bridge/interface
 */

// =============================================================================
// INBOUND MESSAGE
// =============================================================================

/** Normalized inbound message from any messaging platform. */
export interface BridgeMessage {
  /** Platform-specific message ID (used for dedup and threading). */
  id: string;

  /** Canonical user identifier (e.g. `15551234567@c.us`, Slack user ID, etc.). */
  senderId: string;

  /** Channel/chat identifier (group, DM, channel, etc.). */
  channelId: string;

  /** Raw text body (after any transcription or image analysis). */
  body: string;

  /** Message type hint for media handling. */
  type: 'text' | 'voice' | 'image' | 'reaction' | 'file';

  /** Whether the message was sent by the bot itself. */
  fromMe: boolean;

  /** If this is a reply, the ID of the parent message. */
  replyToMessageId?: string;

  /** Platform-specific participant ID (for group messages). */
  participantId?: string;

  /** Raw media payload when type is voice/image/file. */
  media?: {
    data: string;          // base64
    mimetype: string;
    filename?: string;
  };

  /** Emoji string when type is 'reaction'. */
  reaction?: string;

  /** Originating platform identifier. */
  platform: Platform;
}

// =============================================================================
// PLATFORM ENUM
// =============================================================================

export type Platform = 'whatsapp' | 'slack' | 'telegram' | 'discord';

// =============================================================================
// SEND OPTIONS
// =============================================================================

/** Options for outbound messages. */
export interface SendOptions {
  /** If set, reply in the thread of this message ID. */
  replyTo?: string;

  /** If set, format as a specific message style (platform-dependent). */
  style?: 'normal' | 'code' | 'error' | 'progress';
}

// =============================================================================
// BRIDGE EVENTS
// =============================================================================

/** Events emitted by a MessagingBridge to the orchestrator. */
export interface BridgeEvents {
  /** Fired when the bridge is connected and ready. */
  ready: () => void;

  /** Fired when the bridge is disconnected. */
  disconnected: (reason: string) => void;

  /** Fired for inbound messages that pass basic filtering. */
  message: (msg: BridgeMessage) => void;

  /** Fired for inbound reactions. */
  reaction: (msg: BridgeMessage) => void;

  /** Fired when QR/auth is required (WhatsApp-specific, optional). */
  authRequired: (data: { qrCode?: string; qrUrl?: string; url?: string }) => void;

  /** Fired on auth success. */
  authenticated: () => void;

  /** Fired on errors. */
  error: (err: Error) => void;
}

// =============================================================================
// ABSTRACT BRIDGE
// =============================================================================

/**
 * Abstract messaging bridge that all platform adapters must implement.
 *
 * The orchestrator (index.ts) manages bridge lifecycle through this interface,
 * and the handler layer sends/receives through it without knowing the platform.
 */
export interface MessagingBridge {
  /** Platform identifier. */
  readonly platform: Platform;

  /** Initialize the bridge (connect, authenticate, start listening). */
  initialize(): Promise<void>;

  /** Send a text message to a user/channel. */
  sendMessage(targetId: string, text: string, options?: SendOptions): Promise<string | undefined>;

  /** Register an event listener. */
  on<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void;

  /** Remove an event listener. */
  off<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void;

  /** Whether the bridge is currently connected and ready. */
  isReady(): boolean;

  /** Gracefully shut down the bridge. */
  destroy(): Promise<void>;
}

// =============================================================================
// BRIDGE REGISTRY
// =============================================================================

/** Maps platform names to their active bridge instances. */
const activeBridges = new Map<Platform, MessagingBridge>();

/** Register a bridge instance for a platform. */
export function registerBridge(bridge: MessagingBridge): void {
  activeBridges.set(bridge.platform, bridge);
}

/** Unregister a bridge instance. */
export function unregisterBridge(platform: Platform): void {
  activeBridges.delete(platform);
}

/** Get a specific bridge by platform. */
export function getBridge(platform: Platform): MessagingBridge | undefined {
  return activeBridges.get(platform);
}

/** Get all active bridges. */
export function getAllBridges(): MessagingBridge[] {
  return Array.from(activeBridges.values());
}

/** Send a message through the appropriate bridge for a target. */
export async function sendViaBridge(
  platform: Platform,
  targetId: string,
  text: string,
  options?: SendOptions,
): Promise<string | undefined> {
  const bridge = activeBridges.get(platform);
  if (!bridge || !bridge.isReady()) return undefined;
  return bridge.sendMessage(targetId, text, options);
}

