/**
 * @fileoverview Platform-agnostic message formatting.
 *
 * Each platform has different formatting conventions:
 * - WhatsApp: *bold*, _italic_, ~strikethrough~, ```code```
 * - Slack: *bold*, _italic_, ~strikethrough~, `code`, ```code```
 * - Telegram: *bold* (Markdown), HTML tags, or MarkdownV2
 * - Discord: **bold**, *italic*, ~~strikethrough~~, `code`, ```code```
 *
 * This module provides a normalize → platform-specific transform pipeline.
 *
 * @module bridge/format
 */

import type { Platform } from './interface.js';

// =============================================================================
// NORMALIZED TOKENS
// =============================================================================

/**
 * Platform-agnostic intermediate representation.
 *
 * We use a simple markdown-like convention as the canonical form:
 * - **bold**
 * - _italic_
 * - `inline code`
 * - ```code block```
 * - Regular text
 */

// =============================================================================
// PLATFORM FORMATTERS
// =============================================================================

/** Maximum message length per platform (characters). */
const MAX_LENGTHS: Record<Platform, number> = {
  whatsapp: 4096,
  slack: 3000,     // Slack recommends under 4000, but 3000 is safer with blocks
  telegram: 4096,
  discord: 2000,
};

/**
 * Convert markdown-style text to WhatsApp formatting.
 * WhatsApp uses: *bold*, _italic_, ~strike~, ```code```
 */
function toWhatsApp(text: string): string {
  return text
    .replace(/\*\*(.+?)\*\*/g, '*$1*')          // **bold** → *bold*
    .replace(/~~(.+?)~~/g, '~$1~');              // ~~strike~~ → ~strike~
  // _italic_ and `code` and ```code``` are already compatible
}

/**
 * Convert markdown-style text to Slack mrkdwn formatting.
 * Slack uses: *bold*, _italic_, ~strike~, `code`, ```code```
 */
function toSlack(text: string): string {
  return text
    .replace(/\*\*(.+?)\*\*/g, '*$1*')          // **bold** → *bold*
    .replace(/~~(.+?)~~/g, '~$1~');              // ~~strike~~ → ~strike~
  // _italic_ and `code` and ```code``` are already compatible
}

/**
 * Convert markdown-style text to Telegram MarkdownV2 formatting.
 * Telegram uses: *bold*, _italic_, ~strike~, `code`, ```code```
 *
 * MarkdownV2 requires escaping special chars outside of entities.
 */
function toTelegram(text: string): string {
  return text
    .replace(/\*\*(.+?)\*\*/g, '*$1*')          // **bold** → *bold*
    .replace(/~~(.+?)~~/g, '~$1~');              // ~~strike~~ → ~strike~
}

/**
 * Convert markdown-style text to Discord formatting.
 * Discord uses standard Markdown: **bold**, *italic*, ~~strike~~, `code`, ```code```
 */
function toDiscord(text: string): string {
  // Discord already uses standard markdown — minimal transforms needed
  return text;
}

/** Map of platform → formatter function. */
const FORMATTERS: Record<Platform, (text: string) => string> = {
  whatsapp: toWhatsApp,
  slack: toSlack,
  telegram: toTelegram,
  discord: toDiscord,
};

// =============================================================================
// PUBLIC API
// =============================================================================

/**
 * Format text for a specific messaging platform.
 *
 * Input should use the canonical markdown convention (**bold**, _italic_, etc.).
 */
export function formatForPlatform(text: string, platform: Platform): string {
  const formatter = FORMATTERS[platform];
  return formatter(text);
}

/**
 * Split a message into platform-appropriate chunks if it exceeds max length.
 *
 * Tries to split on paragraph boundaries, then sentence boundaries, then
 * hard-cuts at max length.
 */
export function chunkForPlatform(text: string, platform: Platform): string[] {
  const maxLen = MAX_LENGTHS[platform];
  if (text.length <= maxLen) return [text];

  const chunks: string[] = [];
  let remaining = text;

  while (remaining.length > 0) {
    if (remaining.length <= maxLen) {
      chunks.push(remaining);
      break;
    }

    // Try paragraph break
    let splitIdx = remaining.lastIndexOf('\n\n', maxLen);
    if (splitIdx <= 0) {
      // Try newline
      splitIdx = remaining.lastIndexOf('\n', maxLen);
    }
    if (splitIdx <= 0) {
      // Try sentence boundary
      splitIdx = remaining.lastIndexOf('. ', maxLen);
      if (splitIdx > 0) splitIdx += 1; // include the period
    }
    if (splitIdx <= 0) {
      // Hard cut
      splitIdx = maxLen;
    }

    chunks.push(remaining.substring(0, splitIdx).trimEnd());
    remaining = remaining.substring(splitIdx).trimStart();
  }

  return chunks;
}

/**
 * Format and chunk a message for a given platform in one call.
 */
export function formatAndChunk(text: string, platform: Platform): string[] {
  const formatted = formatForPlatform(text, platform);
  return chunkForPlatform(formatted, platform);
}

/** Get max message length for a platform. */
export function getMaxLength(platform: Platform): number {
  return MAX_LENGTHS[platform];
}

