/**
 * @fileoverview Slack bridge adapter using @slack/bolt.
 *
 * Supports:
 * - App mentions (@fetch) and direct messages
 * - Thread replies for context continuation
 * - File uploads for task artifacts
 * - Emoji reactions for approval/rejection workflows
 *
 * @module bridge/slack
 */

import { App, type GenericMessageEvent } from '@slack/bolt';
import { logger } from '../../utils/logger.js';
import { env } from '../../config/env.js';
import type { MessagingBridge, BridgeEvents, BridgeMessage, SendOptions, Platform } from '../interface.js';
import { formatForPlatform } from '../format.js';

// =============================================================================
// SLACK BRIDGE
// =============================================================================

export class SlackBridge implements MessagingBridge {
  readonly platform: Platform = 'slack';

  private app: App | null = null;
  private _isReady = false;
  private botUserId: string | null = null;
  private eventListeners = new Map<keyof BridgeEvents, Set<(...args: any[]) => void>>();

  /** @inheritdoc */
  async initialize(): Promise<void> {
    const botToken = env.SLACK_BOT_TOKEN as string | undefined;
    const appToken = env.SLACK_APP_TOKEN as string | undefined;

    if (!botToken || !appToken) {
      throw new Error('SLACK_BOT_TOKEN and SLACK_APP_TOKEN are required for Slack integration');
    }

    this.app = new App({
      token: botToken,
      appToken: appToken,
      socketMode: true,
      // Disable built-in ack — we handle it ourselves
    });

    this.setupEventHandlers();
    await this.app.start();

    // Resolve bot user ID for self-message filtering
    try {
      const authResult = await this.app.client.auth.test({ token: botToken });
      this.botUserId = authResult.user_id as string || null;
    } catch {
      logger.warn('Could not resolve Slack bot user ID');
    }

    this._isReady = true;
    this.emitBridgeEvent('authenticated');
    this.emitBridgeEvent('ready');
    logger.success('Slack bridge connected and listening');
  }

  /** @inheritdoc */
  isReady(): boolean {
    return this._isReady;
  }

  /** @inheritdoc */
  async sendMessage(targetId: string, text: string, options?: SendOptions): Promise<string | undefined> {
    if (!this.app) return undefined;

    try {
      const formatted = formatForPlatform(text, 'slack');
      const result = await this.app.client.chat.postMessage({
        channel: targetId,
        text: formatted,
        ...(options?.replyTo ? { thread_ts: options.replyTo } : {}),
      });
      return result.ts as string | undefined;
    } catch (err) {
      logger.error(`Failed to send Slack message to ${targetId}`, err);
      return undefined;
    }
  }

  /** @inheritdoc */
  on<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(listener as (...args: any[]) => void);
  }

  /** @inheritdoc */
  off<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void {
    this.eventListeners.get(event)?.delete(listener as (...args: any[]) => void);
  }

  /** @inheritdoc */
  async destroy(): Promise<void> {
    this._isReady = false;
    if (this.app) {
      await this.app.stop();
      this.app = null;
    }
    logger.info('Slack bridge destroyed');
  }

  // ===========================================================================
  // INTERNALS
  // ===========================================================================

  private emitBridgeEvent<K extends keyof BridgeEvents>(event: K, ...args: Parameters<BridgeEvents[K]>): void {
    const listeners = this.eventListeners.get(event);
    if (!listeners) return;
    for (const fn of listeners) {
      try {
        (fn as (...a: any[]) => void)(...args);
      } catch (err) {
        logger.error(`Slack bridge event listener error (${event})`, err);
      }
    }
  }

  private setupEventHandlers(): void {
    if (!this.app) return;

    // Handle app mentions (@fetch in channels)
    this.app.event('app_mention', async ({ event, say }) => {
      try {
        const msg = this.normalizeSlackMessage(event, false);
        if (!msg) return;
        this.emitBridgeEvent('message', msg);
      } catch (err) {
        logger.error('Slack app_mention handler error', err);
      }
    });

    // Handle direct messages
    this.app.event('message', async ({ event }) => {
      try {
        const genericEvent = event as GenericMessageEvent;

        // Skip bot's own messages
        if (genericEvent.bot_id || genericEvent.user === this.botUserId) return;

        // Skip message subtypes (edits, deletes, etc.) except thread replies
        if (genericEvent.subtype && genericEvent.subtype !== 'thread_broadcast') return;

        // Only process DMs (im) — channel messages require @mention
        if (genericEvent.channel_type !== 'im') return;

        const msg = this.normalizeSlackMessage(genericEvent, false);
        if (!msg) return;
        this.emitBridgeEvent('message', msg);
      } catch (err) {
        logger.error('Slack message handler error', err);
      }
    });

    // Handle emoji reactions for approval/rejection
    this.app.event('reaction_added', async ({ event }) => {
      try {
        // Only process reactions from non-bot users
        if (event.user === this.botUserId) return;

        const reactionMsg: BridgeMessage = {
          id: `reaction-${event.event_ts}`,
