      : text;

    if (!stripped) return null;

    return {
      id: event.ts || event.event_ts || `${Date.now()}`,
      senderId: event.user || '',
      channelId: event.channel || '',
      body: stripped,
      type: 'text',
      fromMe: event.user === this.botUserId,
      replyToMessageId: event.thread_ts,
      platform: 'slack',
    };
  }
}

