/**
 * @fileoverview Telegram bridge adapter using telegraf.
 *
 * Supports:
 * - Bot commands and mentions
 * - Voice note transcription (via Fetch's existing Whisper pipeline)
 * - Group chats with @bot mention filtering
 * - Reply-based thread context
 *
 * @module bridge/telegram
 */

import { Telegraf, type Context } from 'telegraf';
import type { Message as TelegramMessage, Update } from 'telegraf/types';
import { logger } from '../../utils/logger.js';
import { env } from '../../config/env.js';
import type { MessagingBridge, BridgeEvents, BridgeMessage, SendOptions, Platform } from '../interface.js';
import { formatForPlatform } from '../format.js';

// =============================================================================
// TELEGRAM BRIDGE
// =============================================================================

export class TelegramBridge implements MessagingBridge {
  readonly platform: Platform = 'telegram';

  private bot: Telegraf | null = null;
  private _isReady = false;
  private botUsername: string | null = null;
  private botId: number | null = null;
  private eventListeners = new Map<keyof BridgeEvents, Set<(...args: any[]) => void>>();

  /** @inheritdoc */
  async initialize(): Promise<void> {
    const token = env.TELEGRAM_BOT_TOKEN as string | undefined;
    if (!token) {
      throw new Error('TELEGRAM_BOT_TOKEN is required for Telegram integration');
    }

    this.bot = new Telegraf(token);

    // Resolve bot info
    const botInfo = await this.bot.telegram.getMe();
    this.botUsername = botInfo.username || null;
    this.botId = botInfo.id;

    this.setupEventHandlers();

    // Launch with graceful stop
    this.bot.launch();

    this._isReady = true;
    this.emitBridgeEvent('authenticated');
    this.emitBridgeEvent('ready');
    logger.success(`Telegram bridge connected as @${this.botUsername}`);
  }

  /** @inheritdoc */
  isReady(): boolean {
    return this._isReady;
  }

  /** @inheritdoc */
  async sendMessage(targetId: string, text: string, options?: SendOptions): Promise<string | undefined> {
    if (!this.bot) return undefined;

    try {
      const formatted = formatForPlatform(text, 'telegram');
      const chatId = targetId;

      const result = await this.bot.telegram.sendMessage(chatId, formatted, {
        parse_mode: 'Markdown',
        ...(options?.replyTo ? { reply_parameters: { message_id: parseInt(options.replyTo, 10) } } : {}),
      });

      return String(result.message_id);
    } catch (err) {
      logger.error(`Failed to send Telegram message to ${targetId}`, err);
      return undefined;
    }
  }

  /** @inheritdoc */
  on<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(listener as (...args: any[]) => void);
  }

  /** @inheritdoc */
  off<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void {
    this.eventListeners.get(event)?.delete(listener as (...args: any[]) => void);
  }

  /** @inheritdoc */
  async destroy(): Promise<void> {
    this._isReady = false;
    if (this.bot) {
      this.bot.stop('Bridge shutdown');
      this.bot = null;
    }
    logger.info('Telegram bridge destroyed');
  }

  // ===========================================================================
  // INTERNALS
  // ===========================================================================

  private emitBridgeEvent<K extends keyof BridgeEvents>(event: K, ...args: Parameters<BridgeEvents[K]>): void {
    const listeners = this.eventListeners.get(event);
    if (!listeners) return;
    for (const fn of listeners) {
      try {
        (fn as (...a: any[]) => void)(...args);
      } catch (err) {
        logger.error(`Telegram bridge event listener error (${event})`, err);
      }
    }
  }

  private setupEventHandlers(): void {
    if (!this.bot) return;

    // Handle text messages
    this.bot.on('text', (ctx) => {
      this.handleTextMessage(ctx);
    });

    // Handle voice messages
    this.bot.on('voice', (ctx) => {
      this.handleVoiceMessage(ctx);
    });

    // Handle photos with captions
    this.bot.on('photo', (ctx) => {
      this.handlePhotoMessage(ctx);
    });
  }

  private handleTextMessage(ctx: Context<Update.MessageUpdate>): void {
    try {
      const message = ctx.message as TelegramMessage.TextMessage;
      if (!message?.text) return;

      // In group chats, only respond to @bot mentions or /fetch commands
      const isGroup = message.chat.type === 'group' || message.chat.type === 'supergroup';
      const hasBotMention = this.botUsername
        ? message.text.includes(`@${this.botUsername}`)
        : false;
      const hasFetchCommand = message.text.startsWith('/fetch');
      const isReply = !!message.reply_to_message;

      if (isGroup && !hasBotMention && !hasFetchCommand && !isReply) {
        return;
      }

      // Strip bot mention and /fetch command prefix
      let body = message.text;
      if (this.botUsername) {
        body = body.replace(new RegExp(`@${this.botUsername}\\s*`, 'g'), '').trim();
      }
      if (body.startsWith('/fetch')) {
        body = body.replace(/^\/fetch\s*/, '').trim();
      }
      if (!body) return;

      const bridgeMsg: BridgeMessage = {
        id: String(message.message_id),
        senderId: String(message.from?.id || ''),
        channelId: String(message.chat.id),
        body,
        type: 'text',
        fromMe: message.from?.id === this.botId,
        replyToMessageId: message.reply_to_message ? String(message.reply_to_message.message_id) : undefined,
        platform: 'telegram',
      };

      this.emitBridgeEvent('message', bridgeMsg);
    } catch (err) {
      logger.error('Telegram text handler error', err);
    }
  }

  private handleVoiceMessage(ctx: Context<Update.MessageUpdate>): void {
    try {
      const message = ctx.message as TelegramMessage.VoiceMessage;
      if (!message?.voice) return;

      const bridgeMsg: BridgeMessage = {
        id: String(message.message_id),
        senderId: String(message.from?.id || ''),
        channelId: String(message.chat.id),
        body: '',
        type: 'voice',
        fromMe: message.from?.id === this.botId,
        platform: 'telegram',
        media: {
          data: '', // Voice file needs to be downloaded via Telegram API
          mimetype: 'audio/ogg',
          filename: `voice-${message.message_id}.ogg`,
        },
      };

      // Store file_id for download — the orchestrator will handle transcription
      (bridgeMsg as any)._telegramFileId = message.voice.file_id;

      this.emitBridgeEvent('message', bridgeMsg);
    } catch (err) {
      logger.error('Telegram voice handler error', err);
    }
  }

  private handlePhotoMessage(ctx: Context<Update.MessageUpdate>): void {
    try {
      const message = ctx.message as TelegramMessage.PhotoMessage;
      if (!message?.photo?.length) return;

      // Get the highest resolution photo
      const photo = message.photo[message.photo.length - 1];
      const caption = (message as any).caption || '';

      const bridgeMsg: BridgeMessage = {
        id: String(message.message_id),
        senderId: String(message.from?.id || ''),
        channelId: String(message.chat.id),
        body: caption,
        type: 'image',
        fromMe: message.from?.id === this.botId,
        platform: 'telegram',
        media: {
          data: '', // Photo needs to be downloaded via Telegram API
          mimetype: 'image/jpeg',
          filename: `photo-${message.message_id}.jpg`,
        },
      };

      // Store file_id for download
      (bridgeMsg as any)._telegramFileId = photo.file_id;

      this.emitBridgeEvent('message', bridgeMsg);
    } catch (err) {
      logger.error('Telegram photo handler error', err);
    }
  }
}

