 *
 * Supports:
 * - Bot mentions (@Fetch) and DMs
 * - Channel-based context (each channel = separate conversation scope)
 * - Role-based access control via Discord roles
 * - Thread replies for context continuation
 * - Reaction-based approval/rejection
 *
 * @module bridge/discord
 */

import {
  Client,
  GatewayIntentBits,
  Partials,
  Events,
  type Message as DiscordMessage,
  type MessageReaction,
  type User as DiscordUser,
  type PartialMessageReaction,
  type PartialUser,
} from 'discord.js';
import { logger } from '../../utils/logger.js';
import { env } from '../../config/env.js';
import type { MessagingBridge, BridgeEvents, BridgeMessage, SendOptions, Platform } from '../interface.js';
import { formatForPlatform, chunkForPlatform } from '../format.js';

// =============================================================================
// DISCORD BRIDGE
// =============================================================================

export class DiscordBridge implements MessagingBridge {
  readonly platform: Platform = 'discord';

  private client: Client | null = null;
  private _isReady = false;
  private eventListeners = new Map<keyof BridgeEvents, Set<(...args: any[]) => void>>();

  /**
   * Optional: restrict bot usage to users with specific Discord roles.
   * Set via DISCORD_ALLOWED_ROLES env (comma-separated role names).
   */
  private allowedRoles: Set<string> | null = null;

  /** @inheritdoc */
  async initialize(): Promise<void> {
    const token = env.DISCORD_TOKEN as string | undefined;
    if (!token) {
      throw new Error('DISCORD_TOKEN is required for Discord integration');
    }

    // Parse optional role-based access control
    const rolesEnv = env.DISCORD_ALLOWED_ROLES as string | undefined;
    if (rolesEnv) {
      this.allowedRoles = new Set(
        rolesEnv.split(',').map((r) => r.trim().toLowerCase()).filter(Boolean)
      );
    }

    this.client = new Client({
      intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMessages,
        GatewayIntentBits.GuildMessageReactions,
        GatewayIntentBits.DirectMessages,
        GatewayIntentBits.MessageContent,
      ],
      partials: [
        Partials.Message,
        Partials.Channel,
        Partials.Reaction,
      ],
    });

    this.setupEventHandlers();

    await this.client.login(token);
    // The 'ready' event handler sets _isReady = true
  }

  /** @inheritdoc */
  isReady(): boolean {
    return this._isReady;
  }

  /** @inheritdoc */
  async sendMessage(targetId: string, text: string, options?: SendOptions): Promise<string | undefined> {
    if (!this.client) return undefined;

    try {
      const channel = await this.client.channels.fetch(targetId);
      if (!channel || !('send' in channel)) {
        logger.warn(`Discord channel ${targetId} not found or not text-based`);
        return undefined;
      }

