      const chunks = chunkForPlatform(formatted, 'discord');

      let lastMsgId: string | undefined;
      for (const chunk of chunks) {
        const sendable = channel as any;
        const msg = await sendable.send({
          content: chunk,
          ...(options?.replyTo ? { reply: { messageReference: options.replyTo } } : {}),
        });
        lastMsgId = msg.id;
      }

      return lastMsgId;
    } catch (err) {
      logger.error(`Failed to send Discord message to ${targetId}`, err);
      return undefined;
    }
  }

  /** @inheritdoc */
  on<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(listener as (...args: any[]) => void);
  }

  /** @inheritdoc */
  off<K extends keyof BridgeEvents>(event: K, listener: BridgeEvents[K]): void {
    this.eventListeners.get(event)?.delete(listener as (...args: any[]) => void);
  }

  /** @inheritdoc */
  async destroy(): Promise<void> {
    this._isReady = false;
    if (this.client) {
      this.client.destroy();
      this.client = null;
    }
    logger.info('Discord bridge destroyed');
  }

  // ===========================================================================
  // INTERNALS
  // ===========================================================================

  private emitBridgeEvent<K extends keyof BridgeEvents>(event: K, ...args: Parameters<BridgeEvents[K]>): void {
    const listeners = this.eventListeners.get(event);
    if (!listeners) return;
    for (const fn of listeners) {
      try {
        (fn as (...a: any[]) => void)(...args);
      } catch (err) {
        logger.error(`Discord bridge event listener error (${event})`, err);
      }
    }
  }

  private setupEventHandlers(): void {
    if (!this.client) return;

    this.client.once(Events.ClientReady, (readyClient) => {
      this._isReady = true;
      this.emitBridgeEvent('authenticated');
      this.emitBridgeEvent('ready');
      logger.success(`Discord bridge connected as ${readyClient.user.tag}`);
    });

    this.client.on(Events.MessageCreate, async (message: DiscordMessage) => {
      try {
        await this.handleMessage(message);
      } catch (err) {
        logger.error('Discord message handler error', err);
      }
    });

    this.client.on(Events.MessageReactionAdd, async (
      reaction: MessageReaction | PartialMessageReaction,
      user: DiscordUser | PartialUser,
    ) => {
      try {
        await this.handleReaction(reaction, user);
      } catch (err) {
        logger.error('Discord reaction handler error', err);
      }
    });

    this.client.on(Events.Error, (error: Error) => {
      this.emitBridgeEvent('error', error);
      logger.error('Discord client error', error);
    });
  }

  private async handleMessage(message: DiscordMessage): Promise<void> {
    // Skip bot messages
    if (message.author.bot) return;

    const isDM = !message.guild;
    const isMentioned = message.mentions.has(this.client!.user!);

    // In guild channels, require @mention; in DMs, always process
    if (!isDM && !isMentioned) return;

    // Role-based access control in guilds
    if (!isDM && this.allowedRoles && message.member) {
      const userRoles = message.member.roles.cache.map((r) => r.name.toLowerCase());
      const hasRole = userRoles.some((r) => this.allowedRoles!.has(r));
      if (!hasRole) {
        logger.debug(`Discord: user ${message.author.tag} lacks required role`);
        return;
      }
    }

    // Strip bot mention from content
    let body = message.content;
    if (this.client?.user) {
      body = body.replace(new RegExp(`<@!?${this.client.user.id}>\\s*`, 'g'), '').trim();
    }
    if (!body) return;

    const bridgeMsg: BridgeMessage = {
      id: message.id,
      senderId: message.author.id,
      channelId: message.channelId,
      body,
      type: 'text',
      fromMe: message.author.id === this.client?.user?.id,
      replyToMessageId: message.reference?.messageId || undefined,
      platform: 'discord',
    };

    // Handle attachments
    const firstAttachment = message.attachments.first();
    if (firstAttachment) {
      if (firstAttachment.contentType?.startsWith('image/')) {
        bridgeMsg.type = 'image';
        bridgeMsg.media = {
          data: '',  // Image URL needs to be fetched
          mimetype: firstAttachment.contentType,
          filename: firstAttachment.name || undefined,
        };
        (bridgeMsg as any)._discordUrl = firstAttachment.url;
      } else if (firstAttachment.contentType?.startsWith('audio/')) {
        bridgeMsg.type = 'voice';
        bridgeMsg.media = {
          data: '',
          mimetype: firstAttachment.contentType,
          filename: firstAttachment.name || undefined,
        };
        (bridgeMsg as any)._discordUrl = firstAttachment.url;
      }
    }

    this.emitBridgeEvent('message', bridgeMsg);
  }

  private async handleReaction(
    reaction: MessageReaction | PartialMessageReaction,
    user: DiscordUser | PartialUser,
  ): Promise<void> {
    // Fetch partial data if needed
    if (reaction.partial) {
      try { reaction = await reaction.fetch(); } catch { return; }
    }
    if (user.partial) {
      try { user = await user.fetch(); } catch { return; }
    }

    // Skip bot reactions
    if (user.bot) return;

    const reactionMsg: BridgeMessage = {
      id: `reaction-${reaction.message.id}-${user.id}`,
      senderId: user.id,
      channelId: reaction.message.channelId,
      body: '',
      type: 'reaction',
      fromMe: false,
      replyToMessageId: reaction.message.id,
      reaction: reaction.emoji.name || undefined,
      platform: 'discord',
    };

    this.emitBridgeEvent('reaction', reactionMsg);
  }
}

