/**
 * @fileoverview Multi-bridge orchestrator.
 *
 * Creates and manages bridge instances for all enabled messaging platforms.
 * Routes inbound messages from non-WhatsApp bridges through the handler layer.
 *
 * WhatsApp remains the primary bridge with its own handler integration
 * (security gates, proactive messaging, etc.). Additional bridges (Slack,
 * Telegram, Discord) use a lighter integration path via the shared handler.
 *
 * @module bridge/orchestrator
 */

import { logger } from '../utils/logger.js';
import { env } from '../config/env.js';
import { handleMessage } from '../handler/index.js';
import type { MessagingBridge, BridgeMessage, Platform } from './interface.js';
import { registerBridge, unregisterBridge } from './interface.js';

// =============================================================================
// ORCHESTRATOR
// =============================================================================

/** All managed bridge instances (including WhatsApp). */
const bridges = new Map<Platform, MessagingBridge>();

/**
 * Initialize and start all enabled non-WhatsApp messaging bridges.
 *
 * WhatsApp is started separately in `startBridge()` because it has its own
 * lifecycle (QR auth, Puppeteer, reconnection logic). This function handles
 * the lighter SDK-based bridges.
 */
export async function startAdditionalBridges(): Promise<void> {
  const enabledPlatforms = getEnabledPlatforms();
  if (enabledPlatforms.length === 0) {
    logger.info('No additional messaging platforms enabled');
    return;
  }

  logger.section('📨 Starting Additional Messaging Bridges');

  for (const platform of enabledPlatforms) {
    try {
      const bridge = await createBridge(platform);
      if (!bridge) continue;

      // Wire up message handling for this bridge
      bridge.on('message', (msg: BridgeMessage) => {
        void handleBridgeMessage(bridge, msg);
      });

      bridge.on('ready', () => {
        logger.success(`${platform} bridge ready`);
      });

      bridge.on('error', (err: Error) => {
        logger.error(`${platform} bridge error: ${err.message}`);
      });

      bridge.on('disconnected', (reason: string) => {
        logger.warn(`${platform} bridge disconnected: ${reason}`);
      });

      await bridge.initialize();
      bridges.set(platform, bridge);
      registerBridge(bridge);

      logger.success(`${platform} bridge started`);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      logger.error(`Failed to start ${platform} bridge: ${msg}`);
      // Non-fatal — other bridges can still start
    }
  }

  logger.divider();
}

/**
 * Shut down all additional bridges.
 */
export async function stopAdditionalBridges(): Promise<void> {
  for (const [platform, bridge] of bridges) {
    try {
      await bridge.destroy();
      unregisterBridge(platform);
      logger.info(`${platform} bridge stopped`);
    } catch (err) {
      logger.warn(`Error stopping ${platform} bridge`, err);
    }
  }
  bridges.clear();
}

/**
 * Get a specific additional bridge by platform.
 */
export function getAdditionalBridge(platform: Platform): MessagingBridge | undefined {
  return bridges.get(platform);
}

// =============================================================================
// INTERNALS
// =============================================================================

/**
 * Determine which additional platforms are enabled via env config.
 */
function getEnabledPlatforms(): Platform[] {
  const platforms: Platform[] = [];

  if (process.env.ENABLE_SLACK === 'true') platforms.push('slack');
  if (process.env.ENABLE_TELEGRAM === 'true') platforms.push('telegram');
  if (process.env.ENABLE_DISCORD === 'true') platforms.push('discord');

  return platforms;
}

/**
 * Dynamically import and instantiate a bridge for the given platform.
 *
 * Uses dynamic imports so the SDK dependencies are only loaded when needed.
 */
async function createBridge(platform: Platform): Promise<MessagingBridge | null> {
  switch (platform) {
    case 'slack': {
      const { SlackBridge } = await import('./slack/index.js');
      return new SlackBridge();
    }
    case 'telegram': {
      const { TelegramBridge } = await import('./telegram/index.js');
      return new TelegramBridge();
    }
    case 'discord': {
      const { DiscordBridge } = await import('./discord/index.js');
      return new DiscordBridge();
    }
    default:
      logger.warn(`Unknown platform: ${platform}`);
      return null;
  }
}

/**
 * Handle an inbound message from a non-WhatsApp bridge.
 *
 * This is a simpler path than WhatsApp's handleIncomingMessage because
 * the SDK bridges handle their own auth (bot tokens) and the platforms
 * have different security models (role-based for Discord, workspace-based
 * for Slack, etc.).
 */
async function handleBridgeMessage(bridge: MessagingBridge, msg: BridgeMessage): Promise<void> {
  if (msg.fromMe || !msg.body) return;

  // Use platform:channelId:senderId as the session user ID
  const sessionUserId = `${msg.platform}:${msg.senderId}`;

  try {
    const responses = await handleMessage(
      sessionUserId,
      msg.body,
      async (text: string) => {
        // Stream progress messages back through the bridge
        await bridge.sendMessage(msg.channelId, text, {
          replyTo: msg.id,
        });
      },
    );

    for (const response of responses) {
      await bridge.sendMessage(msg.channelId, response, {
        replyTo: msg.id,
      });
    }
  } catch (err) {
    logger.error(`Failed to handle ${msg.platform} message`, err);
    await bridge.sendMessage(msg.channelId, 'Sorry, I encountered an error processing your request.', {
      replyTo: msg.id,
    });
  }
}

