          id: `reaction-${event.event_ts}`,
          senderId: event.user,
          channelId: event.item.type === 'message' ? (event.item as any).channel : '',
          body: '',
          type: 'reaction',
          fromMe: false,
          replyToMessageId: event.item.type === 'message' ? (event.item as any).ts : undefined,
          reaction: event.reaction,
          platform: 'slack',
        };
        this.emitBridgeEvent('reaction', reactionMsg);
      } catch (err) {
        logger.error('Slack reaction handler error', err);
      }
    });
  }

  /**
   * Normalize a Slack event into a BridgeMessage.
   */
  private normalizeSlackMessage(
    event: any,
    _isReaction: boolean,
  ): BridgeMessage | null {
    const text = (event.text || '').trim();
    if (!text) return null;

    // Strip bot mention from text (e.g., "<@U12345> do something" → "do something")
    const stripped = this.botUserId
      ? text.replace(new RegExp(`<@${this.botUserId}>\\s*`, 'g'), '').trim()
      : text;

    if (!stripped) return null;

    return {
      id: event.ts || event.event_ts || `${Date.now()}`,
      senderId: event.user || '',
      channelId: event.channel || '',
      body: stripped,
      type: 'text',
      fromMe: event.user === this.botUserId,
      replyToMessageId: event.thread_ts,
      platform: 'slack',
    };
  }
}
